// JamMixer and JamMixerPart are exported alongside their definitions below.

interface TimerState {
  isRunning: boolean;
  elapsedSeconds: number;
  mode: 'countUp' | 'countDown';
  targetSeconds: number;
}

interface MetronomeState {
  bpm: number;
  isPlaying: boolean;
  /** Silence the click audio without stopping the beat clock. Timing still
   *  advances (including the beat-dot display); the playClick call just
   *  bails before it schedules any sound. */
  muted: boolean;
  /** Click volume, 0–100. */
  volume: number;
  beatsPerMeasure: number;
  /** Time signature bottom number (note value that gets the beat). Clicks
   *  per bar = beatsPerMeasure; BPM counts this note value. */
  beatUnit: number;
  subdivision: 'quarter' | 'eighth' | 'sixteenth' | 'eighthTriplet' | 'sixteenthTriplet';
  emphasizeFirstBeat: boolean;
  soundType: 'synth' | 'asrx';
}

export interface SelectedChord {
  note: string;
  type: string;
  symbol: string;
  roman: string;
  /** A chord from the v2 chord builder carries its own intervals (semitones
   *  above the root), so any chord can be shown — not just `chordTypes`. */
  intervals?: number[];
}

interface NoteState {
  selectedNote: string | null;
  selectedScale: string | null;
  currentNoteIndex: number;
  nextNoteIndex: number;
  changeMode: 'none' | 'bars' | 'time';
  changeInterval: number;
  randomize: boolean;
  showNextNote: boolean;
  autoAdvanceEnabled: boolean;
  selectedChord: SelectedChord | null;
  /** Guitar tuning as an array of open-string note names, in display order
   *  (high-E first, low-E last). Default is standard EADGBE. Everything
   *  downstream — fretboard note names, voicing search, interval analysis —
   *  derives from this array. Change tuning → everything re-renders. */
  tuning: string[];
}

interface ChordProgressionState {
  selectedProgression: string | null;
  currentChordIndex: number;
  autoAdvance: boolean;
  barsPerChord: number;
  keyType: 'major' | 'minor';
  selectedStyle: string;
  showProgression: boolean;
}

interface CircleOfFifthsState {
  autoAdvance: boolean;
  direction: 'clockwise' | 'counterclockwise';
  changeMode: 'none' | 'bars' | 'time' | 'beats';
  changeInterval: number;
  randomize: boolean;
  showNext: boolean;
  nextNote: string | null;
  countIn: number;
}

/** A location on the fretboard. Note name derives from (stringIndex, fret, tuning)
 *  at read time via fretboard[stringIndex][fret].note — never stored. This
 *  means changing tuning automatically updates every derived note name with
 *  no migration or reconciliation. */
export interface FretPosition {
  stringIndex: number;
  fret: number;
}

// One entry per base note placed on the HarmonyMaker fretboard. Insertion
// order of `notes` is also the play order surfaced in the analysis panel.
export interface HarmonyNote {
  stringIndex: number;
  fret: number;
  interval: IntervalSpec;  // per-note spec — overrides are simply a value diff
  voicingIdx: number;      // index into the currently-computed voicings list
  /** false = placed since the last Apply, so no harmony yet (v2). Missing
   *  (older saves, v1) counts as harmonized. */
  harmonized?: boolean;
  /** A harmony spot the player picked (v2); otherwise the card chooses one. */
  harmonyAt?: FretPosition;
}

interface HarmonyMakerState {
  notes: HarmonyNote[];
  defaultInterval: IntervalSpec;
}

export interface JamMixer {
  /** Master output level — controls the engine's master gain node.
   *  Range 0-150 where 100 = unity. No mute (Play/Stop covers that role). */
  master:  { volume: number };
  chords:  { volume: number; muted: boolean };
  bass:    { volume: number; muted: boolean };
  strum:   { volume: number; muted: boolean };
  drums:   { volume: number; muted: boolean };
}

/** Parts that have a mute toggle (everything except master). */
export type JamMixerPart = 'chords' | 'bass' | 'strum' | 'drums';

interface JamState {
  mode: 'preset' | 'infinite';
  isPlaying: boolean;
  currentChordIndex: number;
  chordQueue: JamChord[];
  queueLength: number;
  selectedPreset: string | null;
  algorithm: JamAlgorithm;
  drumPattern: DrumPatternName;
  /** How many bars each chord is held before advancing. 1-16.
   *  (Scheduler multiplies by 4 internally to get beats, assuming 4/4.) */
  barsPerChord: number;
  /** Count-in bars before the first chord plays. 0 = disabled. Whole bars
   *  so the first chord always lands on a downbeat in any meter. */
  countIn: number;
  walkState: WalkState;
  mixer: JamMixer;
}

type NoteReadingMode = 'staff' | 'fretboard' | 'phrase';

interface NoteReadingState {
  mode: NoteReadingMode;
  fretCount: 12 | 24;
  /** When mode === 'phrase', how many bars of chords per phrase (1–4). */
  phraseBars: 1 | 2 | 3 | 4;
  /** null → pick a random key each phrase; otherwise lock to this key. */
  phraseKey: string | null;
  phraseNotesPerBar: NotesPerBar;
  /** Which clefs to show. At least one must be enabled. */
  trebleEnabled: boolean;
  bassEnabled: boolean;
  /** When mode === 'phrase', the currently-active generated melody. */
  phraseMelody: Melody | null;
  /** When mode === 'phrase', which note within the melody is the current target. */
  phraseNoteIndex: number;
  prompt: NoteReadingPrompt | null;
  answerState: 'waiting' | 'correct';
  /** Answers pressed wrong this round (piano MIDI or note-name label). */
  wrongPresses: NoteReadingAnswer[];
  /** The answer that was correct. */
  justPressedCorrect: NoteReadingAnswer | null;
  hadWrongThisRound: boolean;
  score: {
    correct: number;
    total: number;
    streak: number;
  };
}

interface CardInfo {
  id: string;
  title: string;
  isActive: boolean;
  layout: 'vertical' | 'horizontal';
}

interface ConfigurationPreset {
  id: string;
  name: string;
  enabledCards: string[];
}

const buildPhrasePrompt = (
  melody: Melody,
  noteIndex: number,
): NoteReadingPrompt => {
  const n = getPlayableNote(melody, noteIndex)!;
  return {
    kind: 'phrase',
    melody,
    noteIndex,
    midi: n.midi,
    spelling: n.spelling,
  };
};

const deriveClefTarget = (treble: boolean, bass: boolean): ClefTarget => {
  if (treble && bass) return 'mixed';
  if (bass) return 'bass';
  return 'treble';
};

const phraseConfigFromState = (nr: {
  phraseBars: number;
  phraseKey: string | null;
  phraseNotesPerBar: NotesPerBar;
  trebleEnabled: boolean;
  bassEnabled: boolean;
}): PhraseConfig => ({
  bars: nr.phraseBars,
  key: nr.phraseKey,
  notesPerBar: nr.phraseNotesPerBar,
  clefTarget: deriveClefTarget(nr.trebleEnabled, nr.bassEnabled),
});

